/**
 * Jinx Hatter + Lil' Monsta: rules tests.
 *
 * Wiki: https://wiki.bloodontheclocktower.com/Hatter
 * Wiki: https://wiki.bloodontheclocktower.com/Lil%27_Monsta
 * (the wiki has no jinx page; each character's page lists the jinx under "Related Jinxes")
 *
 * Generated by `npm run scaffold:rules-tests`, then filled in (L116). Each test quotes the
 * jinx as the wiki words it, word for word, in a `// Wiki: "..."` comment (Trevor, 2026-11-01).
 */
import { describe, expect, it } from 'vitest';
import { findJinx, jinxesAmong } from '#lib/core/data/index.ts';
import { committedGameData } from '#lib/core/testing/committed-data.ts';
import { changeableSeats } from '#lib/core/rules/becomes.ts';
import { gameEnds } from '#lib/core/rules/game-end.ts';
import { alsoBecomes, jinxRulesBetween } from '#lib/core/rules/jinxes.ts';
import { scenario } from '#lib/core/testing/scenario.ts';
import { babysits, scriptOf, withLilMonsta } from './lilmonsta.test-support.ts';

describe("Hatter + Lil' Monsta jinx", () => {
	const data = committedGameData();
	const jinx = findJinx(data.jinxes, 'hatter', 'lilmonsta');

	it('is in jinxes.json between two official characters', () => {
		expect(data.byId.get('hatter')?.name).toBe('Hatter');
		expect(data.byId.get('lilmonsta')?.name).toBe("Lil' Monsta");
		expect(jinx).toBeDefined();
		expect(jinx?.reason).not.toBe('');
	});

	it('applies only when both characters are on the script', () => {
		expect(jinxesAmong(data.jinxes, ['hatter', 'lilmonsta'])).toContain(jinx);
		expect(jinxesAmong(data.jinxes, ['hatter'])).not.toContain(jinx);
		expect(jinxesAmong(data.jinxes, ['lilmonsta'])).not.toContain(jinx);
	});

	// Both pages' Related Jinxes: Lil' Monsta is never dealt, so at the tea party a Demon who
	// picks it also picks a Minion and becomes that; the Minions then choose who babysits. The
	// Hatter's step opens a second picker of Minions (`ChangeCharacterStep`, e2e/jinxes.e2e.ts).
	describe('a Demon who chooses Lil’ Monsta at the tea party also chooses a Minion', () => {
		const cast = ['hatter', 'imp', 'poisoner', 'chef', 'empath', 'monk'];
		const base = withLilMonsta(cast).dies('hatter');

		it("is data in the Hatter's rules", () => {
			expect(jinxRulesBetween('hatter', 'lilmonsta')).toEqual({ alsoBecomes: { type: 'minion' } });
		});

		it('asks for a Minion when the Demon chooses Lil’ Monsta, and for nothing else', () => {
			// Wiki: "If the Hatter dies & the Demon chooses Lil' Monsta, they also choose a Minion to
			// become."
			expect(changeableSeats(base.game, 'hatter', base.characters)).toContain(base.seat('imp'));
			expect(alsoBecomes(base.game, 'hatter', 'lilmonsta', base.characters)).toBe('minion');
			expect(alsoBecomes(base.game, 'hatter', 'vigormortis', base.characters)).toBeUndefined();
			const plain = scenario(cast, { script: scriptOf(cast) });
			expect(alsoBecomes(plain.game, 'hatter', 'lilmonsta', plain.characters)).toBeUndefined();
		});

		it('the Demon becomes the Minion, and the game goes on once a babysitter is chosen', () => {
			// Wiki: "If the Hatter dies & the Demon chooses Lil' Monsta, they also choose a Minion to
			// become."
			const changed = base.do((s) => ({
				type: 'AssignCharacter',
				seatId: s.seat('imp'),
				characterId: 'spy',
				by: 'hatter'
			}));
			expect(changed.game.seats[changed.seat('imp')].characterId).toBe('spy');
			const sat = babysits(changed, 'poisoner');
			expect(gameEnds(sat.game, sat.characters)).toEqual([]);
		});
	});
});
